mapper.update:
UPDATE 
	ADMIN_COMMENT 
SET 
	  USER_ID = #{userId}
	, BOARD_NO = #{boardNo}
	, BOARD_COMMENT_CONTENT = #{boardCommentContent}
	, BOARD_WRITE_DATE = #{boardWriteDate}
	, BOARD_DELETE_DATE = #{boardDeleteDate}
	, BOARD_COMMENT_STATUS = 'U'
WHERE 
	BOARD_COMMENT_NO = #{boardCommentNo}

UPDATE ADMIN_COMMENT 
SET 
	  BOARD_DELETE_DATE = #{boardDeleteDate}
	, BOARD_COMMENT_STATUS = 'D'
WHERE 
	BOARD_COMMENT_NO = #{boardCommentNo}
